nodes = [18,26,59,102,150,168,173,196,216,248,255,269]
start,end = 33039,45039
# consider supports anywhere but require t_close inside window
results = []
for (u1,v1,t1) in events:
    if u1 not in nodes and v1 not in nodes:
        # but support could be between node in list and any r; need at least one of pair is in nodes
        pass
# Better: consider all pairs i,j from nodes, find any interactions where they close inside window
for i_idx,i in enumerate(nodes):
    for j in nodes[i_idx+1:]:
        # find closings in window between i and j
        closings = [t for (u,v,t) in events if set((u,v))==set((i,j)) and start<=t<=end]
        for t_close in closings:
            # find any supports: events where i interacted with r at time t_i and j interacted with r at time t_j, with max(t_i,t_j) <= t_close and t_close - max(t_i,t_j) <=800
            for (u1,v1,t1) in events:
                r1 = v1 if u1==i else (u1 if v1==i else None)
                if r1 is None: continue
                for (u2,v2,t2) in events:
                    r2 = v2 if u2==j else (u2 if v2==j else None)
                    if r2 is None: continue
                    if r1!=r2: continue
                    t_support = max(t1,t2)
                    if t_support<=t_close and t_close - t_support <=800:
                        results.append({'i':i,'j':j,'r':r1,'t_i':t1,'t_j':t2,'t_support':t_support,'t_close':t_close,'delay':t_close-t_support})

print('Found closures with support possibly outside window:', len(results))
for r in results[:50]:
    print(r)
